UPDATE `configurations` SET `config_value` = '{\"ProductGroup\":[{\"productName\":\"First Time Buyer\",\"productRef\":\"FIRST.TIME.BUYER\",\"productDescription\":{\"notes\":\"Flexibility to make overpayments.|+|Choose the length of your term. You can take up to 30 years so that your monthly payments suit your needs.\"},\"imageDetails\":[{\"imageUrl\":\"money_bag.png\",\"imageType\":\"Icon\"}]},{\"productName\":\"Remortgage\",\"productRef\":\"REMORTGAGE\",\"productDescription\":{\"notes\":\"Apply for a remortgage loan and get a better interest rate.|+|Switch your mortgage loan and choose to apply for additional loan amount.|+|Avail zero processing fees on your remortgage loan.|+|Enjoy flexible monthly repayment options with a tenure of up to 360 months.\"},\"imageDetails\":[{\"imageUrl\":\"money_bag.png\",\"imageType\":\"Icon\"}]}],\"ProductDetail\":[{\"ProductName\":\"First Time Buyer\",\"productRef\":\"FIRST.TIME.BUYER\",\"ProductDescription\":\"FirstTimeBuyer\",\"purposeName\":\"First time buyer\",\"ProductDetailedDescription\":\"Stepping onto mortgage ladder, Find out how to buy a home and take out a mortgage.\",\"desc\":\"Deposit: We usually ask for 10% of the amount you want to borrow as a deposit.\",\"ProductNotes\":\"Flexibility to make overpayments.|+|Choose the length of your term. You can take up to 30 years so that your monthly payments suit your needs.\",\"imageDetails\":[{\"imageUrl\":\"landingpage_3_mortgageImg1.png\",\"imageType\":\"Icon\"}],\"ProductTermsAndConditions\":\"1 Estimate obtained based on the information provided by the user. It does not constitute an offer for the application for a mortgage loan.<br>2 The application, granting and amount of the mortgage Loan will be subject to subsequent approval by our risks department.<br>3 Provided that you fulfil all our eligibilty requirements for a mortgage Loan.<br>4 Actual loan eligible amount depends on various factors such as credit history, prevailing interest rates and bank\'s credit policy.\"},{\"ProductName\":\"Remortgage\",\"productRef\":\"REMORTGAGE\",\"ProductDescription\":\"Remortgage\",\"purposeName\":\"Remortgage\",\"ProductDetailedDescription\":\"Transfer your existing mortgage loan held with another lender to us.\",\"desc\":\"Get a remortgage loan worth up to 90% of your current property value.\",\"ProductNotes\":\"Apply for a remortgage loan and get a better interest rate.|+|Switch your mortgage loan and choose to apply for additional loan amount.|+|Avail zero processing fees on your remortgage loan.|+|Enjoy flexible monthly repayment options with a tenure of up to 360 months.\",\"imageDetails\":[{\"imageUrl\":\"landingpage_3_mortgageImg1.png\",\"imageType\":\"Icon\"}],\"ProductTermsAndConditions\":\"1 Estimate obtained based on the information provided by the user. It does not constitute an offer for the application for a mortgage loan.<br>2 The application, granting and amount of the mortgage Loan will be subject to subsequent approval by our risks department.<br>3 Provided that you fulfil all our eligibilty requirements for a mortgage Loan.<br>4 Actual loan eligible amount depends on various factors such as credit history, prevailing interest rates and bank\'s credit policy.\"}],\"mcmsProductId\":\"MORTGAGE.OFFER\"}' WHERE (`configuration_id` = '170');
